-- =============================================================================
-- Auto Business — Gochar (Transit) Phal (migration 017)
-- Owner-editable text banks for the Gochar prediction panel:
--   gochar_house_phal  — Layer 1: 9 planets x 12 houses (from Chandra Lagna)
--   gochar_natal_phal  — Layer 3: transit-over-natal combination texts
-- Structural rules (shubh houses, vedha, triggers, degree timing) live in
-- code (GocharRepository/GocharPhalEngine) with a tajik-style config flag.
-- Rules source: docs/Gochar_Rules.md. Seed matches the baked GocharData.php.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS gochar_house_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    planet VARCHAR(12) NOT NULL, house TINYINT NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    shubh TINYINT NOT NULL DEFAULT 0, text_hi TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_ghp (planet, house, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE shubh=VALUES(shubh),text_hi=VALUES(text_hi);

CREATE TABLE IF NOT EXISTS gochar_natal_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    transit_planet VARCHAR(16) NOT NULL, natal_planet VARCHAR(16) NOT NULL,
    seq SMALLINT NOT NULL DEFAULT 1, language VARCHAR(8) NOT NULL DEFAULT 'hi',
    cond_hi VARCHAR(255) NOT NULL DEFAULT '', text_hi TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_gnp (transit_planet, natal_planet, seq, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE cond_hi=VALUES(cond_hi),text_hi=VALUES(text_hi);

ON DUPLICATE KEY UPDATE cfg_value=cfg_value;
-- End of migration 017.
